import{d as b,C as a,o as h,c,j as n,a as t,E as l,a3 as i}from"./chunks/framework.Q4yG9rk_.js";const p=JSON.parse('{"title":"系辞下传","description":"《易传》之总纲下篇——从卦爻之变、观象制器，到忧患意识与察言观势，讲《易》如何从天地之理落到现实中的行动。","frontmatter":{"title":"系辞下传","description":"《易传》之总纲下篇——从卦爻之变、观象制器，到忧患意识与察言观势，讲《易》如何从天地之理落到现实中的行动。","category":"guide","aliases":["系辞下传","系辞下","xi ci zhuan xia"],"source":["《周易·系辞下传》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/shi-yi/xi-ci-zhuan-xia.md","filePath":"yijing/shi-yi/xi-ci-zhuan-xia.md","lastUpdated":1790587309000}'),w={name:"yijing/shi-yi/xi-ci-zhuan-xia.md"},y=b({...w,setup(g){const s=[{id:"duan-01",label:"一、八卦成列",showLabel:!0,sentences:[["八卦成列，象在其中矣；因而重之，爻在其中矣；刚柔相推，变在其中焉；系辞焉而命之，动在其中矣。吉凶悔吝者，生乎动者也；刚柔者，立本者也；变通者，趣时者也。"]],note:["八卦排成序列，卦象就在其中；两两相重，爻就在其中；刚柔互相推移，变化就在其中；附上卦爻辞加以命名，变动就在其中。吉凶悔吝都生于「动」，刚柔是立卦的根本，变通则是随时而趋。"]},{id:"duan-02",label:"二、贞夫一者也",showLabel:!0,sentences:[["吉凶者，贞胜者也；天地之道，贞观者也；日月之道，贞明者也；天下之动，贞夫一者也。夫乾，确然示人易矣；夫坤，隤然示人简矣。"]],note:["吉凶，是守正者胜；天地之道，是守正而可观；日月之道，是守正而光明；天下之动，是守正于「一」。乾刚健而确然示人以易，坤柔顺而隤然示人以简。"]},{id:"duan-03",label:"三、爻象动乎内",showLabel:!0,sentences:[["爻也者，效此者也。象也者，像此者也；爻象动乎内，吉凶见乎外，功业见乎变，圣人之情见乎辞。"]],note:["爻是效法这个道理的，象是摹拟这个道理的；爻象动于内，吉凶显于外，功业见于变化，圣人的情志见于卦爻辞。"]},{id:"duan-04",label:"四、天地之大德",showLabel:!0,sentences:[["天地之大德曰生，圣人之大宝曰位。何以守位？曰仁。何以聚人？曰财。理财正辞、禁民为非曰义。"]],note:["天地最大的德是「生」，圣人最宝贵的「位」。靠什么守住位？靠仁。靠什么聚集人？靠财。理好财用、端正名分、禁止百姓为非，就是义。"]},{id:"duan-05",label:"五、伏羲作八卦",showLabel:!0,sentences:[["古者包犠氏之王天下也，仰则观象于天，俯则观法于地，观鸟兽之文与地之宜，近取诸身，远取诸物，于是始作八卦，以通神明之德，以类万物之情。"]],note:["古时伏羲氏治理天下，仰观天象、俯察地理，看鸟兽的纹理与土地的所宜，近取于自身、远取于万物，于是开始制作八卦，用来通神明之德、类万物之情。"]},{id:"duan-06",label:"六、作网罟取离",showLabel:!0,sentences:[["作结绳而为网罟，以佃以渔，盖取诸《离》。"]],note:["编结绳做成网罟，用来打猎捕鱼，大概是取法于《离》卦。"]},{id:"duan-07",label:"七、神农作耒耜",showLabel:!0,sentences:[["包犠氏没，神农氏作，斫木为耜，揉木为耒，耒耨之利，以教天下，盖取诸《益》。"]],note:["伏羲氏之后，神农氏兴起，砍木做成耜、揉木做成耒，把耕种的便利教给天下，大概是取法于《益》卦。"]},{id:"duan-08",label:"八、日中为市",showLabel:!0,sentences:[["日中为市，致天下之民，聚天下之货，交易而退，各得其所，盖取诸《噬嗑》。"]],note:["正午设立市集，招来天下之民、聚集天下之货，交换之后各自散去、各得其所，大概是取法于《噬嗑》卦。"]},{id:"duan-09",label:"九、通其变使民不倦",showLabel:!0,sentences:[["神农氏没，黄帝、尧、舜氏作，通其变，使民不倦，神而化之，使民宜之。"]],note:["神农氏之后，黄帝、尧、舜相继兴起，通晓变化的道理，使百姓不倦怠；神妙地化成万物，使百姓各得其宜。"]},{id:"duan-10",label:"十、穷则变",showLabel:!0,sentences:[["《易》穷则变，变则通，通则久。是以“自天祐之，吉无不利”。"]],note:["《易》的道理是：穷极了就要变，变了就能通，通了就能久。所以说「自天祐之，吉无不利」。"]},{id:"duan-11",label:"十一、垂衣裳而治",showLabel:!0,sentences:[["黄帝、尧、舜垂衣裳而天下治，盖取诸《乾》、《坤》。"]],note:["黄帝、尧、舜垂衣拱手而天下大治，大概是取法于《乾》《坤》两卦。"]},{id:"duan-12",label:"十二、刳木为舟",showLabel:!0,sentences:[["刳木为舟，剡木为楫，舟楫之利，以济不通，致远以利天下，盖取诸《涣》。"]],note:["挖空木头做成船、削尖木头做成桨，舟楫的便利在于渡越不通之处、到达远方以利天下，大概是取法于《涣》卦。"]},{id:"duan-13",label:"十三、服牛乘马",showLabel:!0,sentences:[["服牛乘马，引重致远，以利天下，盖取诸《随》。"]],note:["驾牛骑马，牵引重物、到达远方以利天下，大概是取法于《随》卦。"]},{id:"duan-14",label:"十四、重门击柝",showLabel:!0,sentences:[["重门击柝，以待暴客，盖取诸《豫》。"]],note:["设置重门、敲击木柝来防备暴徒，大概是取法于《豫》卦。"]},{id:"duan-15",label:"十五、断木为杵",showLabel:!0,sentences:[["断木为杵，掘地为臼，杵臼之利，万民以济，盖取诸《小过》。"]],note:["截断木头做成杵、挖地做成臼，杵臼的便利使万民得以生活，大概是取法于《小过》卦。"]},{id:"duan-16",label:"十六、弦木为弧",showLabel:!0,sentences:[["弦木为弧，剡木为矢，弧矢之利，以威天下，盖取诸《睽》。"]],note:["绷弦于木做成弓、削尖木条做成箭，弓矢的便利在于威服天下，大概是取法于《睽》卦。"]},{id:"duan-17",label:"十七、易之以宫室",showLabel:!0,sentences:[["上古穴居而野处，后世圣人易之以宫室，上栋下宇，以待风雨，盖取诸《大壮》。"]],note:["上古之人穴居野处，后世的圣人改以宫室，上有栋梁、下有屋檐，用来防备风雨，大概是取法于《大壮》卦。"]},{id:"duan-18",label:"十八、古之葬者",showLabel:!0,sentences:[["古之葬者，厚衣之以薪，葬之中野，不封不树，丧期无数。"]],note:["古时安葬，只用柴薪厚厚地裹着，葬在野外，不起坟也不种树，守丧也没有规定的期限。"]},{id:"duan-19",label:"十九、易之以棺椁",showLabel:!0,sentences:[["后世圣人易之以棺椁，盖取诸《大过》。"]],note:["后世的圣人改以棺椁安葬，大概是取法于《大过》卦。"]},{id:"duan-20",label:"二十、易之以书契",showLabel:!0,sentences:[["上古结绳而治，后世圣人易之以书契，百官以治，万民以察，盖取诸《夬》。"]],note:["上古用结绳记事来治理，后世圣人改用书契，百官得以治事、万民得以明察，大概是取法于《夬》卦。"]},{id:"duan-21",label:"二十一、易者象也",showLabel:!0,sentences:[["是故《易》者，象也；象也者，像也。彖者，材也；爻也者，效天下之动者也。是故吉凶生而悔吝著也。"]],note:["所以《易》就是「象」，象就是「像」；彖是裁断卦材的，爻是效法天下变动的。因此吉凶由此而生，悔吝由此而显。"]},{id:"duan-22",label:"二十二、阳卦多阴",showLabel:!0,sentences:[["阳卦多阴，阴卦多阳，其故何也？阳卦奇，阴卦耦。其德行何也？阳一君而二民，君子之道也。阴二君而一民，小人之道也。"]],note:["阳卦多阴爻、阴卦多阳爻，是什么缘故？因为阳卦为奇、阴卦为偶。它的德行如何？阳卦是一君二民，是君子之道；阴卦是二君一民，是小人之道。"]},{id:"duan-23",label:"二十三、憧憧往来",showLabel:!0,sentences:[["《易》曰：“憧憧往来，朋从尔思。”"]],note:["《易》上说：「往来不绝、心思不定，朋友便顺从你的心思。」"]},{id:"duan-24",label:"二十四、天下何思何虑",showLabel:!0,sentences:[["子曰：“天下何思何虑？天下同归而殊途，一致而百虑。天下何思何虑？日往则月来，月往则日来，日月相推而明生焉。寒往则暑来，暑往则寒来，寒暑相推而岁成焉。往者屈也，来者信也，屈信相感而利生焉。尺蠖之屈，以求信也；龙蛇之蛰，以存身也。精义入神，以致用也；利用安身，以崇德也。过此以往，未之或知也；穷神知化，德之盛也。”"]],note:["孔子说：天下有什么可思可虑的呢？天下同归而路径不同，一致而思虑百端。日往则月来、月往日来，日月相推而光明生；寒往则暑来、暑往则寒来，寒暑相推而年岁成。往就是屈，来就是伸，屈伸相感而利生——尺蠖屈身是为了伸展，龙蛇蛰伏是为了存身；精义入神是为了致用，利用安身是为了崇德；再往前，就不是人所能知的了——穷神知化，是德的极盛。"]},{id:"duan-25",label:"二十五、困于石",showLabel:!0,sentences:[["《易》曰：“困于石，据于蒺藜，入于其宫，不见其妻，凶。”"]],note:["《易》上说：「被石头困住，凭据在蒺藜之上，回到家中却见不到妻子，凶。」"]},{id:"duan-26",label:"二十六、非所困而困焉",showLabel:!0,sentences:[["子曰：“非所困而困焉，名必辱。非所据而据焉，身必危。既辱且危，死期将至，妻其可得见耶！”"]],note:["孔子说：不该受困的地方却受了困，名声必受辱；不该凭据的地方却去凭据，自身必有危险。既受辱又危险，死期将至，妻子哪里还能见得到呢！"]},{id:"duan-27",label:"二十七、公用射隼",showLabel:!0,sentences:[["《易》曰：“公用射隼于高墉之上，获之，无不利。”"]],note:["《易》上说：「王公在高墙上射鹰隼，射获了它，没有不利。」"]},{id:"duan-28",label:"二十八、藏器于身",showLabel:!0,sentences:[["子曰：“隼者，禽也；弓矢者，器也；射之者，人也。君子藏器于身，待时而动，何不利之有？动而不括，是以出而有获，语成器而动者也。”"]],note:["孔子说：隼是禽鸟，弓矢是器具，射它的是人。君子把器具藏在身上，等待时机才行动，哪有不吉利的？一动而不受拘碍，所以出手便有收获——说的就是器具已成而后动。"]},{id:"duan-29",label:"二十九、小人不耻不仁",showLabel:!0,sentences:[["子曰：“小人不耻不仁，不畏不义，不见利不劝，不威不惩。小惩而大诫，此小人之福也。《易》曰：‘履校灭趾，无咎。’此之谓也。”"]],note:["孔子说：小人不以不仁为耻，不畏惧不义，不见利就不肯努力，不施威就不知惩戒。受到小的惩罚而得到大的警诫，正是小人的福气。《易》上说「脚上戴着刑具、伤了脚趾，无咎」，说的就是这个。"]},{id:"duan-30",label:"三十、善不积",showLabel:!0,sentences:[["善不积不足以成名，恶不积不足以灭身。小人以小善为无益而弗为也，以小恶为无伤而弗去也，故恶积而不可掩，罪大而不可解。"]],note:["善行不累积就不足以成名，恶行不累积也不足以灭身。小人以为小善无益而不去做，以为小恶无害而不肯改，所以恶行累积到无法遮掩，罪过大到无法开解。"]},{id:"duan-31",label:"三十一、何校灭耳",showLabel:!0,sentences:[["《易》曰：“何校灭耳，凶。”"]],note:["《易》上说：「肩上扛着刑具、遮住了耳朵，凶。」"]},{id:"duan-32",label:"三十二、安不忘危",showLabel:!0,sentences:[["子曰：“危者，安其位者也；亡者，保其存者也；乱者，有其治者也。是故君子安而不忘危，存而不忘亡，治而不忘乱，是以身安而国家可保也。”"]],note:["孔子说：危险，来自安于其位；灭亡，来自自恃其存；祸乱，来自自恃其治。所以君子安而不忘危、存而不忘亡、治而不忘乱，因此自身安稳而国家可保。"]},{id:"duan-33",label:"三十三、其亡其亡",showLabel:!0,sentences:[["《易》曰：“其亡其亡，系于苞桑。”"]],note:["《易》上说：「快要亡了！快要亡了！——只有像系在丛生的桑树上那样牢固，才能保全。」"]},{id:"duan-34",label:"三十四、德薄而位尊",showLabel:!0,sentences:[["子曰：“德薄而位尊，知小而谋大，力少而任重，鲜不及矣。”"]],note:["孔子说：德行浅薄而地位尊贵，智慧狭小而图谋远大，力量微弱而责任重大——这样的人很少有不遭殃的。"]},{id:"duan-35",label:"三十五、鼎折足",showLabel:!0,sentences:[["《易》曰：“鼎折足，覆公餗，其形渥，凶。”言不胜其任也。"]],note:["《易》上说：「鼎足折断，倾覆了王公的美食，鼎身沾得一片狼藉，凶。」说的是不能胜任其职。"]},{id:"duan-36",label:"三十六、知几其神乎",showLabel:!0,sentences:[["子曰：“知几其神乎！君子上交不谄，下交不渎，其知几乎？几者，动之微，吉之先见者也。君子见几而作，不俟终日。”"]],note:["孔子说：知道「几」，真是神妙啊！君子对上不谄媚、对下不轻慢，这就是知道「几」吧？几，是变动的微小端倪、吉凶的先兆。君子见到几就行动，不等到一天过完。"]},{id:"duan-37",label:"三十七、介于石",showLabel:!0,sentences:[["《易》曰：“介于石，不终日，贞吉。”介如石焉，宁用终日？断可识矣。君子知微知彰，知柔知刚，万夫之望。"]],note:["《易》上说：「坚介如石，不等到一天过完，守正则吉。」像石头那样坚介，何须用一整天？当下就能判明。君子知微也知彰、知柔也知刚，是万众所仰望的人。"]},{id:"duan-38",label:"三十八、颜氏之子",showLabel:!0,sentences:[["子曰：“颜氏之子，其殆庶几乎？有不善未尝不知，知之未尝复行也。《易》曰：‘不远复，无祗悔，元吉。’”"]],note:["孔子说：颜氏之子大概接近了吧！有了不善未尝不知道，知道了未尝再犯。《易》上说「走不远就返回，没有大的悔恨，大吉」。"]},{id:"duan-39",label:"三十九、天地絪温",showLabel:!0,sentences:[["天地絪温，万物化醇。男女构精，万物化生。"]],note:["天地之气氤氲交感，万物化育醇厚；男女交合其精，万物化生不已。"]},{id:"duan-40",label:"四十、三人行",showLabel:!0,sentences:[["《易》曰：“三人行则损一人，一人行则得其友。”言致一也。"]],note:["《易》上说：「三人同行就会减损一人，一人独行则会得到同伴。」说的是专一致一。"]},{id:"duan-41",label:"四十一、安身而后动",showLabel:!0,sentences:[["子曰：“君子安其身而后动，易其心而后语，定其交而后求。君子修此三者，故全也。危以动，则民不与也；惧以语，则民不应也；无交而求，则民不与也。莫之与，则伤之者至矣。”"]],note:["孔子说：君子先安定自身而后行动，先平易其心而后言语，先确定交谊而后求助。君子修此三者，所以能保全。自身危险而行动，百姓不跟从；心存恐惧而言语，百姓不响应；没有交谊而求助，百姓不肯给——无人相助，那么伤害你的人就来了。"]},{id:"duan-42",label:"四十二、莫益之",showLabel:!0,sentences:[["《易》曰：“莫益之，或击之，立心勿恒，凶。”"]],note:["《易》上说：「没有人来增益他，反而有人来攻击他；立心不能恒久，凶。」"]},{id:"duan-43",label:"四十三、易之门",showLabel:!0,sentences:[["子曰：“乾坤，其《易》之门耶？”"]],note:["孔子说：乾坤大概就是《易》的门户吧？"]},{id:"duan-44",label:"四十四、乾阳物也",showLabel:!0,sentences:[["乾，阳物也；坤，阴物也。阴阳合德，而刚柔有体。以体天地之撰，以通神明之德。其称名也，杂而不越。于稽其类，其衰世之意邪？"]],note:["乾是阳物，坤是阴物；阴阳合德而刚柔有体，以此体察天地所撰，以此通神明之德。它的称名虽杂却不越分——考察它的类，大概是衰世的意思吧？"]},{id:"duan-45",label:"四十五、彰往察来",showLabel:!0,sentences:[["夫《易》，彰往而察来，而微显阐幽，开而当名，辨物正言断辞，则备矣。其称名也小，其取类也大。其旨远，其辞文，其言曲而中，其事肆而隐。因贰以济民行，以明失得之报。"]],note:["《易》彰明既往而察知将来，使隐微的显现、幽暗的阐发；开列而各当其名，辨物正言、断以辞——于是完备。它的称名小，所取之类大；意旨深远，文辞有采；言语曲折而中肯，叙事直陈而含隐。因疑贰而济民之行，以明失得之报。"]},{id:"duan-46",label:"四十六、易之兴也",showLabel:!0,sentences:[["《易》之兴也，其于中古乎？作《易》者，其有忧患乎？"]],note:["《易》的兴起，大概在中古吧？作《易》的人，大概有忧患吧？"]},{id:"duan-47",label:"四十七、履，德之基",showLabel:!0,sentences:[["是故《履》，德之基也；"]],note:["所以《履》卦，是德的根基——依礼而行，德行才有立足处。"]},{id:"duan-48",label:"四十八、谦，德之柄",showLabel:!0,sentences:[["《谦》，德之柄也；"]],note:["《谦》卦，是德的把柄——谦才能持守不失。"]},{id:"duan-49",label:"四十九、复，德之本",showLabel:!0,sentences:[["《复》，德之本也；"]],note:["《复》卦，是德的根本——能返归本初，德才有所生。"]},{id:"duan-50",label:"五十、恒，德之固",showLabel:!0,sentences:[["《恒》，德之固也；"]],note:["《恒》卦，是德的坚固——长久不易，德才立得住。"]},{id:"duan-51",label:"五十一、损，德之修",showLabel:!0,sentences:[["《损》，德之修也；"]],note:["《损》卦，是德的修治——减损私欲，德才得以修明。"]},{id:"duan-52",label:"五十二、益，德之裕",showLabel:!0,sentences:[["《益》，德之裕也；"]],note:["《益》卦，是德的充裕——日有所增，德才宽裕。"]},{id:"duan-53",label:"五十三、困，德之辨",showLabel:!0,sentences:[["《困》，德之辨也；"]],note:["《困》卦，是德的辨察——处困境才能看出德的真假。"]},{id:"duan-54",label:"五十四、井，德之地",showLabel:!0,sentences:[["《井》，德之地也；"]],note:["《井》卦，是德的所在地——如井养人不穷，德有其安处。"]},{id:"duan-55",label:"五十五、巽，德之制",showLabel:!0,sentences:[["《巽》，德之制也。"]],note:["《巽》卦，是德的裁制——顺而入，德才有所节制。"]},{id:"duan-56",label:"五十六、履，和而至",showLabel:!0,sentences:[["《履》，和而至；"]],note:["《履》卦，和顺而能到达。"]},{id:"duan-57",label:"五十七、谦，尊而光",showLabel:!0,sentences:[["《谦》，尊而光；"]],note:["《谦》卦，尊贵而愈见光明。"]},{id:"duan-58",label:"五十八、复，小而辨物",showLabel:!0,sentences:[["《复》，小而辨于物；"]],note:["《复》卦，虽微小却能与物相辨——一阳初生，已别于众阴。"]},{id:"duan-59",label:"五十九、恒，杂而不厌",showLabel:!0,sentences:[["《恒》，杂而不厌；"]],note:["《恒》卦，虽处纷杂而不厌倦。"]},{id:"duan-60",label:"六十、损，先难而后易",showLabel:!0,sentences:[["《损》，先难而后易；"]],note:["《损》卦，先难而后易——减损之初难，习久则易。"]},{id:"duan-61",label:"六十一、益，长裕不设",showLabel:!0,sentences:[["《益》，长裕而不设；"]],note:["《益》卦，长久宽裕而不须刻意造作。"]},{id:"duan-62",label:"六十二、困，穷而通",showLabel:!0,sentences:[["《困》，穷而通；"]],note:["《困》卦，穷困而终能通达。"]},{id:"duan-63",label:"六十三、井，居所而迁",showLabel:!0,sentences:[["《井》，居其所而迁；"]],note:["《井》卦，安处其位而能迁惠于人。"]},{id:"duan-64",label:"六十四、巽，称而隐",showLabel:!0,sentences:[["《巽》，称而隐。"]],note:["《巽》卦，称量合宜而不露形迹。"]},{id:"duan-65",label:"六十五、履以和行",showLabel:!0,sentences:[["《履》以和行；"]],note:["《履》卦，用来和顺地践行。"]},{id:"duan-66",label:"六十六、谦以制礼",showLabel:!0,sentences:[["《谦》以制礼；"]],note:["《谦》卦，用来裁制礼节。"]},{id:"duan-67",label:"六十七、复以自知",showLabel:!0,sentences:[["《复》以自知；"]],note:["《复》卦，用来反观自知。"]},{id:"duan-68",label:"六十八、恒以一德",showLabel:!0,sentences:[["《恒》以一德；"]],note:["《恒》卦，用来专一其德。"]},{id:"duan-69",label:"六十九、损以远害",showLabel:!0,sentences:[["《损》以远害；"]],note:["《损》卦，用来远离祸害。"]},{id:"duan-70",label:"七十、益以兴利",showLabel:!0,sentences:[["《益》以兴利；"]],note:["《益》卦，用来兴办有利之事。"]},{id:"duan-71",label:"七十一、困以寡怨",showLabel:!0,sentences:[["《困》以寡怨；"]],note:["《困》卦，用来减少怨尤。"]},{id:"duan-72",label:"七十二、井以辨义",showLabel:!0,sentences:[["《井》以辨义；"]],note:["《井》卦，用来辨明义理。"]},{id:"duan-73",label:"七十三、巽以行权",showLabel:!0,sentences:[["《巽》以行权。"]],note:["《巽》卦，用来施行权变。"]},{id:"duan-74",label:"七十四、不可为典要",showLabel:!0,sentences:[["《易》之为书也不可远，为道也屡迁，变动不居，周流六虚，上下无常，刚柔相易，不可为典要，唯变所适。"]],note:["《易》这部书不可疏远，它的道屡屡迁移：变动而不止息，周流于六虚之间，上下没有定准，刚柔互相交易——不可以当作固定的典要，只能随着变化而适应。"]},{id:"duan-75",label:"七十五、出入以度",showLabel:!0,sentences:[["其出入以度外内，使知惧。又明于忧患与故。"]],note:["它的出入有法度，使人在外在内都知道戒惧；又明晓忧患与事故。"]},{id:"duan-76",label:"七十六、无有师保",showLabel:!0,sentences:[["无有师保，如临父母。初率其辞而揆其方，既有典常。苟非其人，道不虚行。"]],note:["即使没有师保，也如同面临父母。开始顺着它的辞去揣度它的方向，久了便有了典常；但若不是那个人，道也不会凭空而行。"]},{id:"duan-77",label:"七十七、殷之末世",showLabel:!0,sentences:[["《易》之兴也，其当殷之末世，周之盛德耶？当文王与纣之事耶？"]],note:["《易》的兴起，大概在殷的末世、周的盛德之时吧？大概正当文王与商纣的时代吧？"]},{id:"duan-78",label:"七十八、其辞危",showLabel:!0,sentences:[["是故其辞危。危者使平，易者使倾。其道甚大，百物不废。惧以终始，其要无咎，此之谓《易》之道也。"]],note:["所以它的辞多危惧之言：危者使之平，易者使之倾。它的道甚大，百物不废；始终怀着戒惧，要点在「无咎」——这就叫做《易》之道。"]},{id:"duan-79",label:"七十九、至健至顺",showLabel:!0,sentences:[["夫乾，天下之至健也，德行恒易以知险。夫坤，天下之至顺也，德行恒简以知阻。能说诸心，能研诸侯之虑，定天下之吉凶，成天下之亹亹者。"]],note:["乾是天下的至健，德行常在简易之中而能知险；坤是天下的至顺，德行常在简约之中而能知阻。它能悦人之心、能研诸侯之虑，确定天下之吉凶、成就天下勤勉之事。"]},{id:"duan-80",label:"八十、变化云为",showLabel:!0,sentences:[["是故变化云为，吉事有祥。象事知器，占事知来。天地设位，圣人成能。人谋鬼谋，百姓与能。"]],note:["所以变化兴作，吉事自有祥兆：象事则知器，占事则知来。天地设定了位置，圣人成就其能；人谋鬼谋，百姓也都参与其中。"]},{id:"duan-81",label:"八十一、八卦以象告",showLabel:!0,sentences:[["八卦以象告，爻彖以情言，刚柔杂居，而吉凶可见矣。变动以利言，吉凶以情迁。"]],note:["八卦以象告知，爻彖以情言说；刚柔杂居，吉凶便可见了。变动以利言，吉凶随情而迁。"]},{id:"duan-82",label:"八十二、爱恶相攻",showLabel:!0,sentences:[["是故爱恶相攻而吉凶生，远近相取而悔吝生，情伪相感而利害生。"]],note:["所以爱恶相攻而吉凶生，远近相取而悔吝生，情伪相感而利害生。"]},{id:"duan-83",label:"八十三、察情辨辞",showLabel:!0,sentences:[["凡《易》之情，近而不相得则凶，或害之，悔且吝。将叛者其辞惭，中心疑者其辞枝，吉人之辞寡，躁人之辞多，诬善之人其辞游，失其守者其辞屈。"]],note:["大凡《易》所言的情，相近而不相得就凶，或者有人害他，悔而且吝。将要叛离的人，其辞惭愧；心里疑惑的人，其辞支离；吉人之辞少，躁人之辞多；诬陷善人的人其辞游移，失去操守的人其辞屈曲。"]}],o=[{id:"g01",term:"趣时",pinyin:"qū shí",meaning:"趋向、合于时势。「变通者，趣时者也」不是随波逐流，而是守住根本后，采取与时位相合的做法。"},{id:"g02",term:"位",pinyin:"wèi",meaning:"爻所处的位置，也指人在天地人事中的职责位置。「圣人之大宝曰位」强调位置意味着承担，而不只是拥有。"},{id:"g03",term:"贞",pinyin:"zhēn",meaning:"正、定、守住根本。「吉凶者，贞胜者也」说的是变化之中仍有可守的正与一，并非只指占问。"},{id:"g04",term:"制器",pinyin:"zhì qì",meaning:"从象所呈现的结构与功能中制作器物、制度和方法。「观象制器」让形上之理落到生活的实际需要。"},{id:"g05",term:"穷",pinyin:"qióng",meaning:"走到尽头、受阻、原有方式难以继续，并不只指贫穷。「穷则变」首先要求看见旧路已经不通。"},{id:"g06",term:"变通",pinyin:"biàn tōng",meaning:"在变化中调整做法，使事理重新流行。「变」不是乱变，「通」也不是只求方便，而是因时而变、通达而久。"},{id:"g07",term:"几",pinyin:"jī",meaning:"事情将动未动的细微征兆，也是吉凶最先显露的地方。「见几而作」要求在苗头阶段辨认并行动。"},{id:"g08",term:"藏器",pinyin:"cáng qì",meaning:"把能力、准备与可用之才蓄积在身。「待时」不是拖延，而是先使自己成为能够承担行动的人。"},{id:"g09",term:"三陈九卦",pinyin:"sān chén jiǔ guà",meaning:"履、谦、复、恒、损、益、困、井、巽九卦的三层排列，分别说明德性根基、具体表现与行动方法。"},{id:"g10",term:"忧患",pinyin:"yōu huàn",meaning:"对失位、失时、失守及其后果的清醒觉察。「作《易》者，其有忧患乎」不是制造焦虑，而是让人预见并修正。"},{id:"g11",term:"无咎",pinyin:"wú jiù",meaning:"不陷入无法挽回的过失，也包含知错能改、及时止损。「其要无咎」是《易》对行动者的基本要求。"},{id:"g12",term:"亹亹",pinyin:"wěi wěi",meaning:"勤勉不倦、不断前进的样子。「成天下之亹亹」指让天下的事业持续生长，而不是一时的兴奋。"},{id:"g13",term:"说诸心",pinyin:"tuō zhū xīn",meaning:"「说」通「悦」，使人心悦诚服，也使疑虑得到安顿；不是迎合，而是让事理真正进入人心。"},{id:"g14",term:"情伪",pinyin:"qíng wěi",meaning:"真实与虚伪，也泛指事情的实际情状与人为伪饰。「情伪相感」说明关系中的真伪会造成不同的利害走向。"}];return(m,e)=>{const d=a("DaoReadingPrelude"),r=a("DaoTextReading"),u=a("DaoKeywordCards");return h(),c("div",null,[e[0]||(e[0]=n("h1",{id:"系辞下传",tabindex:"-1"},[t("系辞下传 "),n("a",{class:"header-anchor",href:"#系辞下传","aria-label":'Permalink to "系辞下传"'},"​")],-1)),l(d,{title:"先读变化如何落入日用",summary:"《系辞下传》承接上传，却把视线从易道之体进一步推向易道之用：卦爻如何呈现变化，圣人如何观象制器，君子如何藏器待时、见几而作，又如何在关系、位置与忧患中守住无咎。全篇九章，像一条从象到器、从器到事、从事到德的路。",points:[{label:"先看象",text:"八卦、重卦、刚柔与爻位，先构成一套观察变化的语言。"},{label:"再看用",text:"观象制器、穷则变通，说明《易》如何进入生计、制度与行动。"},{label:"最后看人",text:"忧患、见几、安身、守位，最终都要求人在变化中承担自己的位置。"}],hint:"下传的心得不宜只当成金句收藏。可以边读原典，边问：这一段看见了什么变化？它要求什么准备？我现在处在怎样的时位？"}),e[1]||(e[1]=i('<h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>《系辞下传》是《易传》下篇，共九章。它不逐卦解释，而是从卦爻、象辞、器用、历史和人事几个层面，说明《易》怎样帮助人认识变化、判断时位并采取合宜的行动。</p><p>如果说《系辞上传》更像是在回答「《易》是什么、它凭什么成立」，那么下传更关心：<strong>变化如何发生，人如何在变化里行动</strong>。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li>它把「象」从解释天地的符号，推进为可以制器、济世、立制的现实方法。</li><li>它把「变通」说得很具体：不是随意改变，而是在困穷处看见条件，守住根本并趋向合宜的时。</li><li>它反复讨论忧患、位置、积累、苗头和关系，提醒人不要把吉凶看成脱离行动的命运标签。</li><li>它最后回到言辞与心术：一个人的爱恶、远近、真伪和守失，都会在行动与说话中显现。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先顺读九章，抓住「象—爻—变—动」与「器—事—德」两条线。</li><li>再读第二、三、六章：它们集中说明观象制器、穷变通久与三陈九卦。</li><li>遇到第四、八、九章的爻辞与爻位，不急着套成占断，先看其中的时、位、关系和行动条件。</li><li>最后读「忧患」诸段，回到自己的处境：我是在积累什么，忽略了什么苗头，又把什么位置和能力混在了一起？</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>八卦成列，爻在其中</strong>：卦象提供结构，爻位提供阶段，刚柔相推而变化发生。</li><li><strong>刚柔立本，变通趣时</strong>：刚柔是根本结构，变通的尺度则在于是否合乎时势。</li><li><strong>观象制器</strong>：网罟、耒耜、舟楫、宫室、书契等，说明象理必须能够改善生活、疏通阻隔。</li><li><strong>穷则变，变则通，通则久</strong>：困穷不是停留在原处的理由，而是重新观察条件、改变做法的契机。</li><li><strong>天地之大德曰生，圣人之大宝曰位</strong>：生是天地的大德，位是承担责任、聚合众人的现实条件。</li><li><strong>三陈九卦</strong>：履、谦、复、恒、损、益、困、井、巽，组成从立足、修德到权变的一条成德路径。</li><li><strong>忧患意识</strong>：善恶由积累而成，安中要知危，见微要能作，始终都不可轻忽。</li><li><strong>察情辨辞</strong>：象以告，爻彖以情言；关系与心术最终会在言辞的多寡、枝蔓、游移和屈曲中显现。</li></ul><h2 id="与六十四卦的联动" tabindex="-1">与六十四卦的联动 <a class="header-anchor" href="#与六十四卦的联动" aria-label="Permalink to &quot;与六十四卦的联动&quot;">​</a></h2><ul><li>三陈九卦可回到对应卦页：履（<code>10-tianzelv</code>）、谦（<code>15-dishanqian</code>）、复（<code>24-dileifu</code>）、恒（<code>32-leifengheng</code>）、损（<code>41-shanzesun</code>）、益（<code>42-fengleiyi</code>）、困（<code>47-zeshukun</code>）、井（<code>48-shuifengjing</code>）、巽（<code>57-xunweifeng</code>）。</li><li>观象制器可对照离、益、噬嗑、涣、随、豫、小过、睽、大壮、大过、夬等卦，观察「取诸某卦」所指向的结构与功能。</li><li>「乾坤，其《易》之门邪」可回到 <code>01-qianweitian</code>（乾）与 <code>02-kunweidi</code>（坤），看阴阳合德如何成为六十四卦的入口。</li><li>「三人行则损一人，一人行则得其友」与复卦、不远复的内容相互照应，可把「致一」放回具体的返正经验中读。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>',12)),l(r,{colophon:"八卦成列 · 观象制器 · 三陈九卦 · 唯变所适",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"系辞下传原文",sections:s,glossary:o}),e[2]||(e[2]=n("blockquote",null,[n("p",null,"注：本页原典采用通行本分章。不同版本在「无／无有」「修／脩」「简／簡」等字形、句读和个别字词上可能有异文，阅读时以所据底本为准。")],-1)),e[3]||(e[3]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[t("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),l(u,{items:[{term:"趣时",pinyin:["qū","shí"],meaning:"趋向、合于时势。「变通者，趣时者也」不是随波逐流，而是守住根本后，采取与时位相合的做法。"},{term:"位",pinyin:["wèi"],meaning:"爻所处的位置，也指人在天地人事中的职责位置。「圣人之大宝曰位」强调位置意味着承担，而不只是拥有。"},{term:"贞",pinyin:["zhēn"],meaning:"正、定、守住根本。「吉凶者，贞胜者也」说的是变化之中仍有可守的正与一，并非只指占问。"},{term:"制器",pinyin:["zhì","qì"],meaning:"从象所呈现的结构与功能中制作器物、制度和方法。「观象制器」让形上之理落到生活的实际需要。"},{term:"穷",pinyin:["qióng"],meaning:"走到尽头、受阻、原有方式难以继续，并不只指贫穷。「穷则变」首先要求看见旧路已经不通。"},{term:"变通",pinyin:["biàn","tōng"],meaning:"在变化中调整做法，使事理重新流行。「变」不是乱变，「通」也不是只求方便，而是因时而变、通达而久。"},{term:"几",pinyin:["jī"],meaning:"事情将动未动的细微征兆，也是吉凶最先显露的地方。「见几而作」要求在苗头阶段辨认并行动。"},{term:"藏器",pinyin:["cáng","qì"],meaning:"把能力、准备与可用之才蓄积在身。「待时」不是拖延，而是先使自己成为能够承担行动的人。"},{term:"三陈九卦",pinyin:["sān","chén","jiǔ","guà"],meaning:"履、谦、复、恒、损、益、困、井、巽九卦的三层排列，分别说明德性根基、具体表现与行动方法。"},{term:"忧患",pinyin:["yōu","huàn"],meaning:"对失位、失时、失守及其后果的清醒觉察。「作《易》者，其有忧患乎」不是制造焦虑，而是让人预见并修正。"},{term:"无咎",pinyin:["wú","jiù"],meaning:"不陷入无法挽回的过失，也包含知错能改、及时止损。「其要无咎」是《易》对行动者的基本要求。"},{term:"亹亹",pinyin:["wěi","wěi"],meaning:"勤勉不倦、不断前进的样子。「成天下之亹亹」指让天下的事业持续生长，而不是一时的兴奋。"},{term:"说诸心",pinyin:["tuō","zhū","xīn"],meaning:"「说」通「悦」，使人心悦诚服，也使疑虑得到安顿；不是迎合，而是让事理真正进入人心。"},{term:"情伪",pinyin:["qíng","wěi"],meaning:"真实与虚伪，也泛指事情的实际情状与人为伪饰。「情伪相感」说明关系中的真伪会造成不同的利害走向。"}]}),e[4]||(e[4]=i('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><blockquote><p>以下内容依据本次整理的心得笔记归纳，保留「原典—理解—日用」的阅读顺序；其中的观点仍属于读者与作者的阶段性理解，不代替经文和注疏本身。</p></blockquote><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《系辞下传》先把《易》的结构重新摆出来：八卦成列而有象，重卦而有爻，刚柔相推而有变，系辞命名而有行动。接着，它把这些抽象结构放回人的生活：人观察天地、鸟兽、身体与万物，制作网罟、农具、舟楫、宫室和书契；人在困穷、等待、交往和治理中，也必须辨别时位、准备和分寸。</p><p>所以，下传不是把「易」变成一套固定答案，而是展示一条路径：<strong>观察情势，取得其象，准备其器，因时而动，守位成德。</strong></p><h3 id="理-为什么要反复讲变、位与忧患" tabindex="-1">理：为什么要反复讲变、位与忧患 <a class="header-anchor" href="#理-为什么要反复讲变、位与忧患" aria-label="Permalink to &quot;理：为什么要反复讲变、位与忧患&quot;">​</a></h3><ul><li>没有刚柔与爻位，变化就会被误解成随机；没有时位，变通就容易变成投机。</li><li>没有器用与制度，义理就停留在语言里，不能真正济人、聚人、安顿生活。</li><li>没有忧患，人在安稳时容易忘危，在小恶和小错中放任积累，直到失去回头的余地。</li><li>没有对关系与言辞的观察，吉凶就会被外推给命运，而看不见爱恶、远近、情伪如何参与结果。</li></ul><h3 id="用-今天怎么进入这一篇" tabindex="-1">用：今天怎么进入这一篇 <a class="header-anchor" href="#用-今天怎么进入这一篇" aria-label="Permalink to &quot;用：今天怎么进入这一篇&quot;">​</a></h3><p>读每一段时，可以留下三问：</p><ul><li>我现在面对的，是一个什么「象」和什么结构，而不只是一个好坏结论？</li><li>我是否已经成器，还是把「待时」当成了拖延，把「变通」当成了逃避根本？</li><li>我身处的时位、关系和能力是否相称，是否有一个尚可修正的「几」？</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《系辞下传》可以这样重新说：</p><p>世界不会停在一个固定答案里。我们先从自然、身体和生活看见结构，再把结构转成工具、方法和秩序；当旧方法走不通，就重新观察条件，调整做法，但不把改变误当成放弃根本。</p><p>真正重要的行动，通常不是最早冲出去，也不是永远等待，而是先把自己做成能够承担事情的人，在苗头出现时看懂它，在位置相称时采取行动。安稳时要记得风险，微小的善恶要看见积累，关系没有建立时不要急于索取。</p><p>《易》最后关心的不是一个人能否预测一切，而是他能否在变化中少犯可避免的错：知道自己在哪里，知道手里有什么，知道什么时候该变、该止、该说、该行，并让自己的言辞和行动经得起回看。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：《系辞下》把《易》从「占筮之书」拉回到「忧患之书」——「作《易》者，其有忧患乎」，又说「不可为典要，唯变所适」：它不给人一套可背的固定答案，而是教人在变动中认出自己这一刻的位置。</p></blockquote><p>这部分先保留为后续心得的汇总区。当前十七则笔记已经按九章归档，后续可以继续在每一段下补充：</p><ul><li>与原典逐句对应的细读；</li><li>与《系辞上传》、六十四卦和其他专题的互文；</li><li>从个人经验出发的现代案例；</li><li>对不同注本、异文和解释分歧的说明。</li></ul><h2 id="延伸阅读-参考来源" tabindex="-1">延伸阅读 / 参考来源 <a class="header-anchor" href="#延伸阅读-参考来源" aria-label="Permalink to &quot;延伸阅读 / 参考来源&quot;">​</a></h2><ul><li>上一篇：<a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang"><code>系辞上传</code></a></li><li>十翼总览：<a href="/Dao/yijing/shi-yi/"><code>孔子十翼</code></a></li><li>相关专题：<a href="/Dao/topics/traditional-wisdom/01-philosophy/03-four-symbols"><code>四象论</code></a>，辨析《系辞》四象与四方四神的两条脉络</li><li>通行本《周易·系辞下传》（王弼注、孔颖达疏系统）</li><li>原典阅读时建议同时对照所采用底本的句读、异文与注疏，不把后世会通解释直接当成经文原义。</li></ul>',21))])}}});export{p as __pageData,y as default};
